-- ═══ history-industrial-revolution — 産業革命の波紋
insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-industrial-revolution', '00000000-0000-4000-8000-b596178c3ba4', '産業革命の波紋', '蒸気機関と紡績機から始まった変化が、都市と経済、そして働く人々の生活をどう作り替えたか。技術・経済と都市・労働と社会運動の三層を重ね、一つの発明が社会全体に広がる波紋を追う。', 'history-politics', 'ja', 'public', 's_history-industrial-revolution', 1712, 1872, 'history-industrial-revolution')
on conflict (slug) do update set owner_id = excluded.owner_id, title = excluded.title, description = excluded.description, category = excluded.category,
  start_year = excluded.start_year, end_year = excluded.end_year, updated_at = now();
delete from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution');
delete from public.events where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution');
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-industrial-revolution'), '技術と発明', 'blue', 0);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-industrial-revolution'), '経済と都市', 'orange', 1);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-industrial-revolution'), '労働と社会運動', 'pink', 2);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1712-01-01', null, 'year', 'point', 'ニューコメンの蒸気機関が稼働', '1712年、トーマス・ニューコメンの大気圧機関がイングランドの炭鉱で排水用に稼働を始めた。人力と畜力と水力しかなかった世界に、燃料から動力を取り出す初めての実用機械が現れた。

効率は低く、用途も鉱山の排水にほぼ限られたが、**石炭を動力に変える**という原理はここで実証された。半世紀後にワットはこの機関の改良から出発する。産業革命という波紋の、最初の一滴にあたる出来事である。', null,
          'verified', null, 'user', 0) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Newcomen atmospheric engine', 'https://en.wikipedia.org/wiki/Newcomen_atmospheric_engine')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1733-01-01', null, 'year', 'point', 'ジョン・ケイ、飛び杼を発明', '1733年、ジョン・ケイが特許を得た飛び杼(フライング・シャトル)は織布の速度をおよそ2倍にし、これまで2人がかりだった広幅の布を1人で織ることを可能にした。

織りが速くなると、今度は糸が足りなくなる。この不均衡が後の紡績機の発明競争を呼び、技術が次の技術を要求する連鎖が始まった。職を奪われることを恐れた織工たちの反発でケイが困窮したという逸話も伝わるが、その細部は検証されていない。', null,
          'unverified', 'ケイが織工の反発を受けて困窮・亡命したという逸話は後世の脚色を含む可能性があり、検証されていない。', 'user', 1) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: John Kay (flying shuttle)', 'https://en.wikipedia.org/wiki/John_Kay_(flying_shuttle)'), ('T.S.アシュトン『産業革命』', null)) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1764-01-01', null, 'year', 'point', 'ハーグリーブスのジェニー紡績機', '織工ジェームズ・ハーグリーブスが、1人で複数の錘(つむ)を同時に回せるジェニー紡績機を作った。家内工業の道具の形のまま、紡績の生産性を数倍に引き上げた発明である。

発明年は1764年とも65年ともされ、ハーグリーブス自身が記録を残さなかったため確定しない。飛び杼が生んだ糸不足への応答であり、まもなくアークライトの水力紡績機と競い合いながら、綿工業を技術革新の主戦場に変えていく。', null,
          'disputed', '発明年は1764〜65年と資料により幅があり、発明の経緯も後年の証言と伝承に依存する。', 'user', 2) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Spinning jenny', 'https://en.wikipedia.org/wiki/Spinning_jenny')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1769-01-05', '1800-12-31', 'day', 'period', 'ワット特許の31年', 'ジェームズ・ワットが、蒸気を別室で冷やす分離凝縮器の特許を取得した。1775年には議会立法で1800年までの延長を勝ち取り、実業家ボールトンとの企業は約30年にわたり改良蒸気機関をほぼ独占的に供給した。

同じ1769年にはアークライトが水力紡績機の特許を得ており、この線の上でクロムフォードの工場も『国富論』も力織機も生まれている。特許制度が発明を資本に変える型はここで整ったが、独占の線が切れた1800年以後に高圧機関の革新が相次いだことから、この31年を技術の足踏みと見る研究もある。', null,
          'disputed', '特許の付与は1769年1月5日。1775年の議会立法で1800年までの延長が認められたが、満了の月日については資料により記載が分かれる。', 'user', 3) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: ジェームズ・ワット', 'https://ja.wikipedia.org/wiki/ジェームズ・ワット')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '経済と都市'),
          '1771-01-01', null, 'year', 'point', 'アークライト、クロムフォードに紡績工場', 'リチャード・アークライトがダーウェント川沿いのクロムフォードに水力紡績工場を建てた。数百人が機械の速度に合わせて交替で働く、近代的な工場制度の原型である。

農村の仕事は季節と日光が区切っていたが、工場では時計が区切る。**時間で管理される労働**という新しい生活の型がここで生まれ、やがて都市へ、そして世界へ広がっていく。工場村クロムフォードを含むダーウェント峡谷は、現在世界遺産に登録されている。', null,
          'verified', null, 'user', 4) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Cromford Mill', 'https://en.wikipedia.org/wiki/Cromford_Mill')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '経済と都市'),
          '1776-03-09', null, 'day', 'point', 'アダム・スミス『国富論』刊行', '1776年3月9日、アダム・スミスの『国富論』が刊行された。ピン工場の分業の観察から説き起こし、市場での交換が社会全体の富を増やしていく仕組みを体系的に描いた。

重商主義的な規制や独占への批判は、その後の自由貿易政策や工場主たちの自己理解を支える理論となった。工業化がまだ始まったばかりの時点で、来たるべき経済社会を語る言葉を先に用意した書物といえる。', null,
          'verified', null, 'user', 5) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 国富論', 'https://ja.wikipedia.org/wiki/国富論')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1785-01-01', null, 'year', 'point', 'カートライトの力織機特許', '聖職者エドマンド・カートライトが、動力で布を織る力織機の特許を取得した。初期の機械は実用性に乏しかったが、改良を重ねて19世紀初頭から普及が進む。

紡績の機械化が生んだ「糸余り」への応答であり、飛び杼以来の技術連鎖がこれで一巡した。手織工は一時は高賃金を享受したが、力織機の普及とともに没落していき、その困窮が労働と社会運動レイヤーのラッダイト運動の背景の一つとなる。', null,
          'verified', null, 'user', 6) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Edmund Cartwright', 'https://en.wikipedia.org/wiki/Edmund_Cartwright')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '労働と社会運動'),
          '1799-07-01', '1824-06-30', 'month', 'period', '団結禁止法の25年', 'フランス革命への警戒が強まるなか、賃上げなどを目的とする労働者の団結を犯罪とする団結禁止法が成立した。以後四半世紀、労働組合は地下に潜り、共済組合などの形を借りて存続することになる。1824年の廃止で、団結はようやく犯罪ではなくなった。

この線の内側に、ラッダイト運動の線とピータールーの点がすっぽり収まっている。交渉の回路を法で塞がれた時代には、機械の破壊と街頭の集会だけが残された表現だった。廃止から労働組合法(1871年)までの半世紀も、この線の続きとして読むことができる。', null,
          'verified', null, 'user', 7) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Combination Act 1799', 'https://en.wikipedia.org/wiki/Combination_Act_1799')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '労働と社会運動'),
          '1811-01-01', '1816-12-31', 'year', 'period', 'ラッダイト運動（機械打ち壊し）', '1811年、ノッティンガムの靴下編工から始まった機械打ち壊しは、伝説の指導者「ネッド・ラッド」の名を掲げてランカシャーやヨークシャーの繊維地帯に広がった。政府は軍を投入し、機械破壊を死刑とする法で応じた。

単純な機械嫌いではなく、賃金切り下げと熟練の無価値化への抗議だった。団結が法で禁じられていた時代、機械の破壊(技術と発明レイヤーの力織機など)は残された交渉手段でもあった。「ラッド」なる人物の実在は確認されていない。', null,
          'verified', null, 'user', 8) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: ラッダイト運動', 'https://ja.wikipedia.org/wiki/ラッダイト運動'), ('E.P.トムスン『イングランド労働者階級の形成』', null)) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '経済と都市'),
          '1815-03-23', '1846-06-26', 'day', 'period', '穀物法の31年', 'ナポレオン戦争の終結直後、地主層の利益を守るため外国産穀物の輸入を制限する穀物法が成立した。パンの価格を高止まりさせるこの法は工場主と労働者の双方から憎まれ、反穀物法同盟の全国運動とアイルランド大飢饉を経て、1846年に廃止される。

この線は、ピータールーの点やチャーティスト運動の線(労働と社会運動レイヤー)と重なって走る。**パンの値段が階級対立の形を決めた**31年であり、廃止をもって英国は自由貿易へ舵を切った。『国富論』が用意した言葉が、70年かけて制度に追いついた期間ともいえる。', null,
          'verified', null, 'user', 9) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Corn Laws', 'https://en.wikipedia.org/wiki/Corn_Laws')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '労働と社会運動'),
          '1819-08-16', null, 'day', 'point', 'ピータールーの虐殺', '1819年8月16日、マンチェスターの聖ピーター広場で議会改革を求めて集まった約6万人の群衆に騎兵隊が突入し、死者十数人、負傷者数百人を出した。ワーテルローをもじって「ピータールー」と呼ばれる。

急成長する工業都市マンチェスターには、当時まだ独自の議席がなかった。**繁栄の中心にいながら発言権を持たない人々**の存在をこの事件は可視化し、1832年の選挙法改正へ続く長い圧力の起点となった。', null,
          'disputed', '死者数は11〜18人、参加者数は6万人前後と、資料により推計に幅がある。', 'user', 10) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Peterloo Massacre', 'https://en.wikipedia.org/wiki/Peterloo_Massacre')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '技術と発明'),
          '1825-09-27', null, 'day', 'point', '世界初の公共鉄道が開業', '1825年9月27日、スティーヴンソンの機関車ロコモーション号が客車と貨車を牽いてストックトン・アンド・ダーリントン鉄道を走った。蒸気機関車が牽く世界初の公共鉄道である。

もとは炭鉱の石炭を港へ運ぶための路線だったが、蒸気機関が「据え付けの動力」から「移動する動力」へ変わった意味は大きい。5年後のリバプール・マンチェスター鉄道(経済と都市レイヤー)で、鉄道の時代が本格的に開く。', null,
          'verified', null, 'user', 11) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Stockton and Darlington Railway', 'https://en.wikipedia.org/wiki/Stockton_and_Darlington_Railway')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '経済と都市'),
          '1830-09-15', null, 'day', 'point', 'リバプール・マンチェスター鉄道開業', '綿工業都市マンチェスターと港湾都市リバプールを結ぶ、時刻表に基づき機関車牽引で運行される初の都市間鉄道が開業した。開業式典では政治家ハスキソンが機関車にひかれて死亡する事故も起きている。

輸送費と移動時間の劇的な短縮は、原料と製品と人と情報の流れを一変させた。以後20年で英国は鉄道網に覆われ、株式投機の熱狂(鉄道狂時代)まで生む。産業革命の波紋が、空間そのものを縮め始めた出来事である。', null,
          'verified', null, 'user', 12) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: Liverpool and Manchester Railway', 'https://en.wikipedia.org/wiki/Liverpool_and_Manchester_Railway')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-industrial-revolution'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-industrial-revolution') and name = '労働と社会運動'),
          '1833-01-01', null, 'year', 'point', '工場法成立、児童労働に国家が介入', '1833年の工場法は、繊維工場での9歳未満の児童の就労を禁じ、年少者の労働時間を制限し、専任の工場監督官を置いた。実効性を備えた初の労働立法とされる。

**自由放任の時代に、国家が工場の門をくぐった**転換点である。監督官の報告書は労働の実態を数字で可視化し、以後の10時間法など一連の工場立法の根拠となった。児童に就学を義務づけた規定は、公教育の整備にもつながっていく。', null,
          'verified', null, 'user', 13) returning id)
