insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-postwar-japan', '00000000-0000-4000-8000-0c3d63d6338e', '日本の戦後復興', '焼け跡の1945年から大阪万博まで25年。政治外交・経済産業・暮らしの3層を重ね、占領改革と国際復帰、成長の光と代償が、家庭の風景をどう変えたかを追う年表。', 'history-politics', 'ja', 'public', 's_history-postwar-japan', 1945, 1970, 'history-postwar-japan')
on conflict (slug) do update set owner_id = excluded.owner_id, title = excluded.title, description = excluded.description, category = excluded.category,
  start_year = excluded.start_year, end_year = excluded.end_year, updated_at = now();
delete from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan');
delete from public.events where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan');
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-postwar-japan'), '政治と外交', 'blue', 0);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-postwar-japan'), '経済と産業', 'gold', 1);
insert into public.layers (timeline_id, name, color, position) values ((select id from public.timelines where slug = 'history-postwar-japan'), '暮らしと文化', 'green', 2);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '政治と外交'),
          '1945-08-15', null, 'day', 'point', '玉音放送、戦争が終わる', '昭和天皇がポツダム宣言受諾を国民にラジオで告げ、日本の戦争は終わった。国土の主要都市は空襲で焦土となり、生産力は崩壊し、海外からは約600万人の引揚げが始まる。

9月2日の降伏文書調印を経て連合国軍の占領下に入り、政治・経済・暮らしのすべてがゼロからの再出発となった。この年表は、この日を起点に25年で大阪万博(暮らしと文化レイヤー)へ至る距離を測るものである。', null,
          'verified', null, 'user', 0) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 玉音放送', 'https://ja.wikipedia.org/wiki/玉音放送')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '政治と外交'),
          '1945-09-02', '1952-04-28', 'day', 'period', '連合国占領下の6年8か月', '1945年9月2日の降伏文書調印から、1952年4月28日の講和条約発効まで、日本は連合国軍の占領下にあった。GHQの指令の下で新憲法、農地改革、財閥解体、教育改革と、戦後日本の骨組みがこの6年8か月の間に据えられた。

この線の中には農地改革の線(経済と産業レイヤー)がすっぽり収まり、朝鮮特需の線は占領の終わりをまたいで独立後まで続く。外からの力による改革の期間として、この年表の政治レイヤーの土台となる線である。', null,
          'verified', null, 'user', 1) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 連合国軍占領下の日本', 'https://ja.wikipedia.org/wiki/連合国軍占領下の日本')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '政治と外交'),
          '1945-10-11', null, 'day', 'point', 'GHQが五大改革を指示', 'マッカーサーが幣原喜重郎首相に、婦人参政権、労働組合の結成奨励、教育の自由化、圧政的諸制度の廃止、経済の民主化のいわゆる五大改革を口頭で指示した。占領改革の骨格を示すものである。

財閥解体・農地改革(経済と産業レイヤー)や新憲法制定はこの延長線上にあり、翌1946年4月の総選挙では女性が初めて投票し39人の女性議員が誕生した。敗戦国の社会構造を外からの力が組み替えていく、占領期の性格を象徴する指令である。', null,
          'verified', null, 'user', 2) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('国立国会図書館「日本国憲法の誕生」資料と解説', 'https://www.ndl.go.jp/constitution/')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '経済と産業'),
          '1946-10-21', '1950-12-31', 'day', 'period', '農地改革の4年、地主制の解体', '第二次農地改革の法律が成立し、不在地主の全小作地などを国が強制買収して小作農に売り渡す事業が1950年ごろまで続いた。小作地の約8割が解放され、大部分の農家が自作農となった。

寄生地主制という戦前農村の骨格を数年で解体した、占領改革でも最も徹底した社会変革とされる。自作農の購買力は後の耐久消費財ブーム(暮らしと文化レイヤー)の基盤となり、農村は保守政治の安定した支持基盤(政治と外交レイヤー)にもなった。', null,
          'verified', null, 'user', 3) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 農地改革', 'https://ja.wikipedia.org/wiki/農地改革')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '政治と外交'),
          '1946-11-03', null, 'day', 'point', '日本国憲法公布', '国民主権・戦争放棄・基本的人権の尊重を三原則とする日本国憲法が公布され、翌1947年5月3日に施行された。天皇は統治権の総攬者から象徴となった。

GHQ草案を基礎に帝国議会の審議で修正を経た制定過程には今も評価の幅があるが、この憲法が**戦後日本の骨格**となったことは動かない。戦力不放棄の下での安全保障をどう確保するかという問いは、講和・安保条約(1951年)から安保闘争(1960年)まで、この年表の政治レイヤーを貫く主題となる。', null,
          'verified', null, 'user', 4) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('国立国会図書館「日本国憲法の誕生」', 'https://www.ndl.go.jp/constitution/')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '経済と産業'),
          '1946-12-27', null, 'day', 'point', '傾斜生産方式を閣議決定', '第1次吉田内閣が、乏しい資材と資金を石炭と鉄鋼に集中投入し、その増産を他産業に波及させる傾斜生産方式を閣議決定した。復興金融金庫の融資がこれを支えた。

統制経済の手法で生産の底割れを止めようとする戦後最初の本格的な経済戦略だったが、復金融資の紙幣増発はインフレーションを激化させ、ドッジ・ラインによる強制的な引き締めを招く伏線となった。石炭増産への実際の寄与については、今日まで経済史家の評価が分かれている。', null,
          'disputed', '政策の存在は確実だが、増産効果がどの程度この方式によるものかは資材配分の実態をめぐって研究上の評価が分かれる。', 'user', 5) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 傾斜生産方式', 'https://ja.wikipedia.org/wiki/傾斜生産方式')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '経済と産業'),
          '1949-03-07', null, 'day', 'point', 'ドッジ・ライン発表、1ドル360円時代へ', 'GHQ財政顧問ドッジが超均衡予算と補助金削減を柱とする経済安定策を発表し、4月には1ドル360円の単一為替レートが設定された。戦後インフレは収束に向かう。

「竹馬の足を切る」と形容された荒療治はデフレ不況と人員整理を招き、労働争議が激化した(政治と外交レイヤーの占領政策転換と連動)。しかし360円レートは以後22年間維持され、輸出主導の高度成長の土台となる。緊縮の痛みの直後に朝鮮特需が訪れる展開は、戦後経済の運の分かれ目だった。', null,
          'verified', null, 'user', 6) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: ドッジ・ライン', 'https://ja.wikipedia.org/wiki/ドッジ・ライン')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '経済と産業'),
          '1950-06-25', '1953-07-27', 'day', 'period', '朝鮮戦争と特需景気の3年', '朝鮮戦争の勃発により、在日米軍からの物資調達とサービス需要が日本経済に流れ込んだ。トラック・繊維から兵器修理まで、いわゆる特需は数十億ドル規模に達したと推計され、ドッジ不況下の企業を一気に立ち直らせた。

**隣国の戦争が復興の燃料になった**という戦後日本の出発点の逆説であり、講和の早期実現(政治と外交レイヤー)と再軍備問題もこの戦争が引き寄せた。トヨタなどはこの受注を「命拾い」と回顧している。', null,
          'disputed', '特需収入の総額は集計範囲(狭義の特需か関連需要を含むか)により10億ドル台から30億ドル超まで推計が分かれる。', 'user', 7) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 朝鮮特需', 'https://ja.wikipedia.org/wiki/朝鮮特需')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'history-postwar-japan') and name = '政治と外交'),
          '1951-09-08', null, 'day', 'point', 'サンフランシスコ講和条約・日米安保条約に調印', '日本は48か国と平和条約に調印し、翌1952年4月28日の発効をもって占領は終わり主権を回復した。同じ日に日米安全保障条約も調印され、米軍の駐留が継続することになった。

ソ連が調印せず中国が招かれない「片面講和」か全面講和かをめぐり国内世論は割れ、独立と引き換えの安保体制という枠組みは、1960年の条約改定(安保闘争)まで持ち越される争点となった。国際社会への復帰と対米依存が同じ日に始まった点が、戦後外交の構図を決めている。', null,
          'verified', null, 'user', 8) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 日本国との平和条約', 'https://ja.wikipedia.org/wiki/日本国との平和条約')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'history-postwar-japan'),
