insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('personal-diet-log', '00000000-0000-4000-8000-ed2351c4d1bd', 'ダイエット記録', '35歳の健診で初めて引っかかってから続けている、体重と健康の記録です。数値の変化と食事・運動の試行錯誤に、健診の制度や世の中の動きを重ねました。急がない減量が習慣になるまでの18年。1973年生まれの会社員の、無理はしない、記録するだけの健康管理です。', 'personal-life', 'ja', 'public', 's_personal-diet-log', 2008, 2026, 'personal-diet-log')
